css:
:root {
  --rv-accent: oklch(0.5464 0.2508 263.51);
  --rv-accent-soft: oklch(0.5464 0.2508 263.51 / 0.149);
  --rv-bg: oklch(0.16 0.015 260);
  --rv-bg-chart: oklch(0.19 0.016 260);
  --rv-bg-elev: oklch(0.205 0.018 260);
  --rv-block-gap: 5rem;
  --rv-brand: oklch(0.70 0.16 264);
  --rv-chart-ink: oklch(1 0 0);
  --rv-density: 1.25;
  --rv-down: oklch(0.68 0.17 25);
  --rv-font-display: Space Grotesk, Inter, sans-serif;
  --rv-font-mono: Geist Mono, JetBrains Mono, ui-monospace, monospace;
  --rv-font-text: Geist, Inter, system-ui, sans-serif;
  --rv-font-ui: Geist, Inter, system-ui, sans-serif;
  --rv-hold: oklch(0.78 0.14 70);
  --rv-ink: oklch(0.95 0.005 260);
  --rv-ink-faint: oklch(0.51 0.014 260);
  --rv-ink-soft: oklch(0.72 0.012 260);
  --rv-line-base: 1.65;
  --rv-link: oklch(0.70 0.16 264);
  --rv-measure: 42rem;
  --rv-radius-m: 12px;
  --rv-radius-s: 12px;
  --rv-report-max-width: 880px;
  --rv-rule: oklch(0.30 0.016 260);
  --rv-rule-soft: oklch(0.29 0.016 260);
  --rv-shadow-float: none;
  --rv-size-base: 16.2px;
  --rv-size-display: 45px;
  --rv-size-h1: 36px;
  --rv-size-h2: 28.8px;
  --rv-size-h3: 19.8px;
  --rv-size-small: 13.5px;
  --rv-up: oklch(0.70 0.15 150);
}
@media (max-width: 640px) {
:root {
  --rv-block-gap: 3rem;
  --rv-size-base: 15.3px;
  --rv-size-display: 34.2px;
  --rv-size-h1: 29.7px;
  --rv-size-h2: 25.2px;
  --rv-size-h3: 18.9px;
  --rv-size-small: 12.6px;
}
}
:root{color-scheme:dark}
:root{--rv-readout-rule:var(--rv-ink-faint)}
:root{--rv-motion-duration:560ms;--rv-motion-easing:cubic-bezier(0.33,1,0.68,1);--rv-motion-stagger:40ms;--rv-motion-distance:14px;--rv-motion-block:none}
.rv-report__body blockquote{font-style:italic}
.rv-callout{border-top-width:1px}
.rv-report__title{letter-spacing:-0.02em}
.rv-chart{background:var(--rv-bg-chart);padding:1rem 1.25rem;border-radius:var(--rv-radius-m)}
.rv-chart.rv-chart--expanded{border:0;background:none;border-radius:0}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
